package com.bookreads.api

import com.bookreads.dto.SessionSyncRequest
import com.bookreads.storage.LocalSessionStore
import kotlinx.coroutines.delay

class SessionSyncService(
    private val sessionRepository: SessionRepository,
    private val localSessionStore: LocalSessionStore,
) {

    suspend fun sync(request: SessionSyncRequest) {
        runCatching { sessionRepository.syncSession(request) }
    }

    suspend fun startPeriodicSync(getRequest: () -> SessionSyncRequest?) {
        while (true) {
            delay(30_000L)
            val request = getRequest() ?: break
            sync(request)
        }
    }
}
```

